package com.phoenix.business.service;
import com.phoenix.business.domain.*;import com.phoenix.business.repository.*;import lombok.RequiredArgsConstructor;import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.stereotype.Service;import java.io.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class ReportService {
 private final MemberRepository members;private final PaymentRepository payments;private final AttendanceRepository attendance;private final BusinessSettingsRepository settings;
 public byte[] members(Member.Status status)throws IOException{var data=members.findAll().stream().filter(m->status==null||m.getStatus()==status).map(m->List.of(n(m.getMemberCode()),n(m.getName()),n(m.getPhone()),n(m.getEmail()),n(m.getStatus()),n(m.getPlan()==null?null:m.getPlan().getName()),n(m.getExpiryDate()))).toList();return workbook("Members Report",List.of("Member ID","Name","Phone","Email","Status","Plan","Expiry"),data);}
 public byte[] payments(LocalDate from,LocalDate to,Payment.Method method)throws IOException{var data=payments.findByPaymentDateBetweenOrderByPaymentDateAsc(start(from),end(to)).stream().filter(p->method==null||p.getMethod()==method).map(p->List.of(n(p.getReceiptNumber()),n(p.getMember().getName()),n(p.getPlanNameSnapshot()),n(p.getPaymentDate()),n(p.getAmount()),n(p.getMethod()),n(p.getStatus()),n(p.getReceivedBy().getDisplayName()))).toList();return workbook("Payments Report",List.of("Receipt","Member","Plan","Date","Amount","Method","Status","Staff"),data);}
 public byte[] attendance(LocalDate from,LocalDate to,Long memberId)throws IOException{var data=attendance.findByCheckedInAtBetween(start(from),end(to)).stream().filter(a->memberId==null||a.getMember().getId().equals(memberId)).map(a->List.of(n(a.getMember().getMemberCode()),n(a.getMember().getName()),n(a.getCheckedInAt()),n(a.getCheckedOutAt()),n(a.getStatus()),n(a.getSource()))).toList();return workbook("Attendance Report",List.of("Member ID","Member","Check-in","Check-out","Status","Source"),data);}
 public byte[] expiring(LocalDate from,LocalDate to)throws IOException{var data=members.findByExpiryDateBetween(or(from,LocalDate.now()),or(to,LocalDate.now().plusDays(30))).stream().map(m->List.of(n(m.getMemberCode()),n(m.getName()),n(m.getPhone()),n(m.getPlan()==null?null:m.getPlan().getName()),n(m.getExpiryDate()),n(m.getStatus()))).toList();return workbook("Expiring Memberships",List.of("Member ID","Name","Phone","Plan","Expiry","Status"),data);}
 public byte[] revenue(LocalDate from,LocalDate to,Payment.Method method)throws IOException{var rows=payments.findByPaymentDateBetweenOrderByPaymentDateAsc(start(from),end(to)).stream().filter(p->p.getStatus()==Payment.Status.PAID&&(method==null||p.getMethod()==method)).toList();Map<LocalDate,java.math.BigDecimal> totals=new TreeMap<>();rows.forEach(p->totals.merge(p.getPaymentDate().atZone(ZoneOffset.UTC).toLocalDate(),p.getAmount(),java.math.BigDecimal::add));List<List<String>> data=new ArrayList<>(totals.entrySet().stream().map(e->List.of(n(e.getKey()),n(e.getValue()))).toList());data.add(List.of("TOTAL",n(rows.stream().map(Payment::getAmount).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add))));return workbook("Revenue Summary",List.of("Date","Paid revenue"),data);}
 private Instant start(LocalDate d){return or(d,LocalDate.now().withDayOfMonth(1)).atStartOfDay(ZoneOffset.UTC).toInstant();}private Instant end(LocalDate d){return or(d,LocalDate.now()).plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();}private LocalDate or(LocalDate value,LocalDate fallback){return value==null?fallback:value;}private String n(Object o){return o==null?"":String.valueOf(o);}
 private byte[] workbook(String title,List<String> heads,List<List<String>> rows)throws IOException{try(Workbook w=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet s=w.createSheet(title);CellStyle h=w.createCellStyle();Font f=w.createFont();f.setBold(true);h.setFont(f);String gym=settings.findById(1L).map(BusinessSettings::getGymName).orElse("Phoenix Gym");s.createRow(0).createCell(0).setCellValue(gym);s.createRow(1).createCell(0).setCellValue(title+" — generated "+Instant.now());Row hr=s.createRow(3);for(int i=0;i<heads.size();i++){Cell c=hr.createCell(i);c.setCellValue(heads.get(i));c.setCellStyle(h);}int r=4;for(List<String> row:rows){Row x=s.createRow(r++);for(int i=0;i<row.size();i++)x.createCell(i).setCellValue(row.get(i));}s.createFreezePane(0,4);s.setAutoFilter(new org.apache.poi.ss.util.CellRangeAddress(3,Math.max(3,r-1),0,heads.size()-1));for(int i=0;i<heads.size();i++){s.autoSizeColumn(i);s.setColumnWidth(i,Math.min(16000,s.getColumnWidth(i)+800));}w.write(out);return out.toByteArray();}}
}
